use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng};
fn main(){counted::disable();println!("p\tsm\tcase\trep\tarm\tmodulus\tk\texpected\tcorrect\trows\tanchors\tt\tcounts");let(mut calls,mut incomplete,mut prefixes)=(0,0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,_,_)=fast_prepare(&c);let base=c.place(fb[0].0,fb[0].1);assert!(c.is_zero(&c.mul(&base,ell)));let mut rng=Rng::new(2026112600^p);for sm in [1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let target=c.mul(&d,expected);let gate=core::solve(&c,&d,&target,ell,true);prefixes+=gate.relations;let mut prior=std::collections::BTreeMap::new();for rep in 0..2{for i in 0..2{let arm=if rep==0{i}else{1-i};counted::reset();let(k,rows,anchors,t)=if arm==0{let r=baseline::solve(&c,&d,&target,ell,false);(r.k,r.relations,r.anchors,r.parameter)}else{let r=core::solve(&c,&d,&target,ell,false);assert_eq!((r.k,r.relations,r.anchors,r.parameter),(gate.k,gate.relations,gate.anchors,gate.parameter));(r.k,r.relations,r.anchors,r.parameter)};let counts=counted::snapshot();counted::disable();let correct=k.is_some_and(|x|x==expected&&c.mul(&d,x)==target);if k.is_some(){assert!(correct)}else{incomplete+=1;}let signature=(k,rows,anchors,t,counts.clone());if rep==1{assert_eq!(prior[&arm],signature)}else{prior.insert(arm,signature);}for(modulus,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{arm}\t{modulus}\t{}\t{expected}\t{correct}\t{rows}\t{anchors}\t{t}\t{}",k.map_or("none".into(),|k|k.to_string()),v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}}}assert_eq!(calls,48);eprintln!("calls={calls} incomplete_calls={incomplete} candidate_prefix_checks={prefixes} exact_repeats=true all_returned_scalars_verify=true fresh_workloads=12");}
